describe('User Registration - Duplicate Email Error', () => {
  const baseUrl = Cypress.env('BASE_URL') || 'http://localhost:3000';
  const testEmail = 'existing@example.com';
  const testPassword = 'SecurePassword123!';
  const testName = 'John Doe';

  beforeEach(() => {
    cy.visit(`${baseUrl}/register`);
    cy.clearCookies();
    cy.clearLocalStorage();
  });

  it('should display error message when registering with an already-used email', () => {
    // First registration with the test email
    cy.get('input[name="name"]').type(testName);
    cy.get('input[name="email"]').type(testEmail);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('input[name="confirmPassword"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    // Wait for successful registration
    cy.url().should('include', '/login');

    // Navigate back to registration page
    cy.visit(`${baseUrl}/register`);

    // Attempt to register with the same email
    cy.get('input[name="name"]').type('Jane Doe');
    cy.get('input[name="email"]').type(testEmail);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('input[name="confirmPassword"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Email already in use');

    // Verify user stays on registration page
    cy.url().should('include', '/register');

    // Verify form fields are not cleared
    cy.get('input[name="email"]').should('have.value', testEmail);
  });

  it('should display error for duplicate email with case-insensitive matching', () => {
    const originalEmail = 'TestUser@Example.com';
    const duplicateEmailDifferentCase = 'testuser@example.com';

    // First registration
    cy.get('input[name="name"]').type(testName);
    cy.get('input[name="email"]').type(originalEmail);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('input[name="confirmPassword"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/login');

    // Navigate back to registration
    cy.visit(`${baseUrl}/register`);

    // Attempt registration with same email in different case
    cy.get('input[name="name"]').type('Another User');
    cy.get('input[name="email"]').type(duplicateEmailDifferentCase);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('input[name="confirmPassword"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Email already in use');

    // Verify error is specific to email field
    cy.get('[data-testid="email-error"]')
      .should('be.visible')
      .and('contain', 'This email is already registered');
  });

  it('should allow registration after correcting duplicate email error', () => {
    const firstEmail = 'user1@example.com';
    const secondEmail = 'user2@example.com';

    // First registration
    cy.get('input[name="name"]').type(testName);
    cy.get('input[name="email"]').type(firstEmail);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('input[name="confirmPassword"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/login');

    // Navigate back to registration
    cy.visit(`${baseUrl}/register`);

    // Attempt with duplicate email
    cy.get('input[name="name"]').type('Jane Doe');
    cy.get('input[name="email"]').type(firstEmail);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('input[name="confirmPassword"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    // Verify error appears
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Clear email field and enter new email
    cy.get('input[name="email"]').clear().type(secondEmail);
    cy.get('button[type="submit"]').click();

    // Verify successful registration
    cy.url().should('include', '/login');
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Registration successful');
  });

  it('should handle rapid duplicate registration attempts gracefully', () => {
    const email = 'rapid@example.com';

    // First registration
    cy.get('input[name="name"]').type(testName);
    cy.get('input[name="email"]').type(email);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('input[name="confirmPassword"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/login');

    // Navigate back and attempt duplicate immediately
    cy.visit(`${baseUrl}/register`);

    cy.get('input[name="name"]').type('Another User');
    cy.get('input[name="email"]').type(email);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('input[name="confirmPassword"]').type(testPassword);

    // Click submit multiple times rapidly
    cy.get('button[type="submit"]').click();
    cy.get('button[type="submit"]').click();

    // Verify only one error message is shown
    cy.get('[data-testid="error-message"]')
      .should('have.length', 1)
      .and('be.visible');

    // Verify submit button is disabled after first attempt
    cy.get('button[type="submit"]').should('be.disabled');
  });
});
